INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `BroadcastTextID0`, `lang0`, `Probability0`) VALUES
(9100001, 'Sveiki atvykę į testų salą! Čia parduodami visi epiniai ir legendiniai šarvai bei ginklai, brangakmeniai, glifai, profesijų medžiagos, vartojami daiktai ir kita.$B$BPrekių kainos – įprastos, todėl aukso gausite pas pagalbininką. Pasirinkite kategoriją.', 'Sveiki atvykę į testų salą! Čia parduodami visi epiniai ir legendiniai šarvai bei ginklai, brangakmeniai, glifai, profesijų medžiagos, vartojami daiktai ir kita.$B$BPrekių kainos – įprastos, todėl aukso gausite pas pagalbininką. Pasirinkite kategoriją.', 0, 0, 1),
(9100002, 'Pasirinkite kategoriją.', 'Pasirinkite kategoriją.', 0, 0, 1),
(9100003, 'Pasirinkite prekių sąrašą.', 'Pasirinkite prekių sąrašą.', 0, 0, 1),
(9100004, 'Aš padedu testuotojams: galiu duoti aukso, pakelti lygį, atstatyti gyvybes ir atšaukti atsinaujinimus, pakelti įgūdžius ir profesijas, o taip pat nukelti į didžiuosius miestus arba atgal, iš kur atvykote.', 'Aš padedu testuotojams: galiu duoti aukso, pakelti lygį, atstatyti gyvybes ir atšaukti atsinaujinimus, pakelti įgūdžius ir profesijas, o taip pat nukelti į didžiuosius miestus arba atgal, iš kur atvykote.', 0, 0, 1),
(9100005, 'Pasirinkite ekipiruotės vietą, kurią norite užkerėti. Aukščiausio lygio užkerėjimus ir prizminius lizdus uždedu nemokamai.', 'Pasirinkite ekipiruotės vietą, kurią norite užkerėti. Aukščiausio lygio užkerėjimus ir prizminius lizdus uždedu nemokamai.', 0, 0, 1),
(9100006, 'Pasirinkite užkerėjimą šiam daiktui. Rodomi tik tie, kurie tinka šio daikto tipui.', 'Pasirinkite užkerėjimą šiam daiktui. Rodomi tik tie, kurie tinka šio daikto tipui.', 0, 0, 1),
(9100007, 'Galiu išmokyti tavo klasės burtų (iki tavo lygio), visų jojimo ir skraidymo įgūdžių, įskaitant skraidymą Šaltuosiuose kraštuose, taip pat visų ginklų ir šarvų, kuriuos gali naudoti tavo klasė.', 'Galiu išmokyti tavo klasės burtų (iki tavo lygio), visų jojimo ir skraidymo įgūdžių, įskaitant skraidymą Šaltuosiuose kraštuose, taip pat visų ginklų ir šarvų, kuriuos gali naudoti tavo klasė.', 0, 0, 1);
